<script setup lang="ts">
import ProjectDateRange from './ProjectDateRange.vue'
import { downloadExcel } from './excel'
import TagPills from './TagPills.vue'
import { computed,nextTick,onUnmounted,ref,watch } from 'vue'
import { account,api } from './api'
import type { LiveProject,ProjectMilestone,ProjectTask } from './project-api'
import ProjectTaskTree from './ProjectTaskTree.vue'
import { projectOptions } from './project-options'
const props=defineProps<{projects:LiveProject[];projectId?:string;refresh:()=>Promise<void>;combined?:boolean;projectTasks?:boolean;projectIds?:string[]}>()
const types=computed(()=>[...new Set([...projectOptions.value.filter(o=>o.scope==='types').map(o=>o.name),...props.projects.map(p=>p.type)])])
const emit=defineEmits<{'open-project':[id:string];'edit-task':[project:LiveProject,task?:ProjectTask,assigneeId?:string]}>()
const collapsed=ref<string[]>([])
const taskGroups=computed(()=>{
 if(props.projectTasks)return props.projects.filter(p=>props.projectIds?.includes(p.id)).map(project=>({id:project.id,milestone:undefined as Row|undefined,project,tasks:project.tasks.slice().sort((a,b)=>(a.due||'9999-12-31').localeCompare(b.due||'9999-12-31'))}))
 const p=props.projects.find(p=>p.id===props.projectId);if(!p)return []
 const used=new Set<string>()
 const groups:{id:string;milestone?:Row;tasks:ProjectTask[];project:LiveProject}[]=p.milestones.slice().sort((a,b)=>a.planned.localeCompare(b.planned)).map(m=>{
  const ids=new Set(m.taskIds);let changed=true;while(changed){changed=false;for(const t of p.tasks)if(t.parentId&&ids.has(t.parentId)&&!ids.has(t.id)){ids.add(t.id);changed=true}}
  const tasks=p.tasks.filter(t=>ids.has(t.id));tasks.forEach(t=>used.add(t.id));return {id:m.id,milestone:{...m,project:p},tasks,project:p}
 });const tasks=p.tasks.filter(t=>!used.has(t.id));if(tasks.length||!groups.length)groups.push({id:'unassigned',milestone:undefined,tasks,project:p});return groups
})
function editTask(project:LiveProject,task:ProjectTask){selectedTask.value=undefined;emit('edit-task',project,task)}
function toggleGroup(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(v=>v!==id):[...collapsed.value,id]}
const states=['待开始','进行中','待验收','已完成','已暂停','已取消'],view=ref('列表'),query=ref(''),projectFilter=ref(''),typeFilter=ref(''),stateFilter=ref(''),ownerFilter=ref(''),priorityFilter=ref(''),dueFilter=ref(''),sort=ref('planned'),page=ref(1),pageSize=ref(25),error=ref(''),busy=ref(false),pendingDelete=ref('')
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
function days(date:string){return Math.round((Date.parse(date)-Date.parse(today()))/86400000)}
function closed(m:ProjectMilestone){return ['已完成','已取消'].includes(m.state)}
function timing(m:ProjectMilestone){if(m.state==='已完成')return m.actual>m.planned?`延期${Math.round((Date.parse(m.actual)-Date.parse(m.planned))/86400000)}天完成`:'按期完成';if(m.state==='已取消')return '已取消';const d=days(m.planned);return d<0?`逾期${-d}天`:d===0?'今天到期':d<=7?`${d}天后到期`:'按计划推进'}
const scoped=computed(()=>props.projects.filter(p=>!props.projectId||p.id===props.projectId)),rows=computed(()=>scoped.value.flatMap(project=>(project.milestones||[]).map(m=>({...m,project}))))
const filtered=computed(()=>rows.value.filter(m=>(!projectFilter.value||m.project.id===projectFilter.value)&&(!typeFilter.value||m.project.type===typeFilter.value)&&(!stateFilter.value||m.state===stateFilter.value)&&(!ownerFilter.value||m.ownerId===ownerFilter.value)&&(!priorityFilter.value||m.priority===priorityFilter.value)&&(!dueFilter.value||(dueFilter.value==='逾期'?!closed(m)&&days(m.planned)<0:dueFilter.value==='7天内'?!closed(m)&&days(m.planned)>=0&&days(m.planned)<=7:m.ownerId===account.value?.id))&&`${m.title} ${m.project.title} ${m.owner} ${m.description} ${m.deliverable} ${m.acceptance} ${m.tags.join(' ')} ${m.result}`.toLowerCase().includes(query.value.trim().toLowerCase())).sort((a,b)=>sort.value==='progress'?b.progress-a.progress:sort.value==='priority'?['高','中','低'].indexOf(a.priority)-['高','中','低'].indexOf(b.priority):sort.value==='updated'?b.updatedAt.localeCompare(a.updatedAt):a.planned.localeCompare(b.planned)))
const owners=computed(()=>Array.from(new Map(rows.value.map(m=>[m.ownerId,m.owner])).entries())),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value))),visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value)),managed=computed(()=>scoped.value.filter(p=>p.canManage))
const stats=computed(()=>({total:filtered.value.length,done:filtered.value.filter(m=>m.state==='已完成').length,overdue:filtered.value.filter(m=>!closed(m)&&days(m.planned)<0).length,soon:filtered.value.filter(m=>!closed(m)&&days(m.planned)>=0&&days(m.planned)<=7).length,review:filtered.value.filter(m=>m.state==='待验收').length}))
watch([query,projectFilter,typeFilter,stateFilter,ownerFilter,priorityFilter,dueFilter,sort,pageSize,view],()=>page.value=1);watch(pages,n=>{page.value=Math.min(n,page.value)})
function reset(){query.value='';projectFilter.value='';typeFilter.value='';stateFilter.value='';ownerFilter.value='';priorityFilter.value='';dueFilter.value=''}
type Row=ProjectMilestone&{project:LiveProject}
const selected=ref<{projectId:string;id:string}>(),editing=ref<{projectId:string;entry?:ProjectMilestone}>()
const selectedTask=ref<{projectId:string;id:string}>()
const taskDetail=computed(()=>{const project=props.projects.find(p=>p.id===selectedTask.value?.projectId);const task=project?.tasks.find(t=>t.id===selectedTask.value?.id);return project&&task?{project,task}:undefined})
const detail=computed(()=>rows.value.find(m=>m.id===selected.value?.id&&m.project.id===selected.value.projectId))
const draft=ref({projectId:'',title:'',ownerId:'',planned:'',actual:'',description:'',deliverable:'',acceptance:'',priority:'中',taskIds:[] as string[],dependsOn:'',tags:'',state:'待开始',progress:0,result:''})
const current=computed(()=>props.projects.find(p=>p.id===draft.value.projectId)),planning=computed(()=>current.value?.canManage)
function selectProject(){draft.value.ownerId=current.value?.ownerId||'';draft.value.taskIds=[];draft.value.dependsOn='';draft.value.planned=current.value?.end||today()}
function edit(row?:Row,duplicate=false){const p=row?.project||managed.value[0];if(!p)return;error.value='';selected.value=undefined;editing.value={projectId:p.id,entry:duplicate?undefined:row};draft.value={projectId:p.id,title:row?(duplicate?row.title+'（副本）':row.title):'',ownerId:row?.ownerId||p.ownerId,planned:row?.planned||p.end||today(),actual:duplicate?'':row?.actual||'',description:row?.description||'',deliverable:row?.deliverable||'',acceptance:row?.acceptance||'',priority:row?.priority||'中',taskIds:row?.taskIds.slice()||[],dependsOn:duplicate?'':row?.dependsOn||'',tags:row?.tags.join('、')||'',state:duplicate?'待开始':row?.state||'待开始',progress:duplicate?0:row?.progress||0,result:duplicate?'':row?.result||''}}
function changeState(){if(draft.value.state==='已完成'){draft.value.progress=100;draft.value.actual= draft.value.actual||today()}else{draft.value.actual='';if(draft.value.state==='待开始')draft.value.progress=0}}
async function save(){busy.value=true;error.value='';try{const old=editing.value?.entry;const data=planning.value?{...draft.value,tags:draft.value.tags.split(/[、,，]/).map(t=>t.trim()).filter(Boolean),revision:old?.revision}:{state:draft.value.state,progress:draft.value.progress,actual:draft.value.actual,result:draft.value.result,revision:old?.revision};await api(`/pm/projects/${draft.value.projectId}/milestones${old?'/'+old.id:''}`,old?'PUT':'POST',data);await props.refresh();editing.value=undefined}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(row:Row){if(pendingDelete.value!==row.id){pendingDelete.value=row.id;return}busy.value=true;error.value='';try{await api(`/pm/projects/${row.project.id}/milestones/${row.id}`,'DELETE',{revision:row.revision});await props.refresh();pendingDelete.value='';selected.value=undefined}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function exportExcel(){const cells=[['项目','里程碑','负责人','计划日期','实际完成日期','状态','进度','优先级','交付成果','验收标准','关联任务','前置节点','标签','执行记录'],...filtered.value.map(m=>[m.project.title,m.title,m.owner,m.planned,m.actual,m.state,String(m.progress)+'%',m.priority,m.deliverable,m.acceptance,m.project.tasks.filter(t=>m.taskIds.includes(t.id)).map(t=>t.title).join('、'),m.project.milestones.find(n=>n.id===m.dependsOn)?.title||'',m.tags.join('、'),m.result])];await downloadExcel('里程碑-筛选结果.xlsx',cells,'里程碑')}
const modal=computed(()=>!!editing.value||!!detail.value||!!taskDetail.value);let previous:HTMLElement|null=null
function keydown(e:KeyboardEvent){if(!modal.value)return;if(e.key==='Escape'&&!busy.value){e.preventDefault();editing.value=undefined;selected.value=undefined;selectedTask.value=undefined}if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.milestone-modal button:not(:disabled),.milestone-modal input:not(:disabled),.milestone-modal select:not(:disabled),.milestone-modal textarea:not(:disabled)'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
watch(modal,async open=>{if(open){previous=document.activeElement as HTMLElement;document.addEventListener('keydown',keydown);await nextTick();document.querySelector<HTMLElement>('.milestone-modal button')?.focus()}else{document.removeEventListener('keydown',keydown);previous?.focus()}});onUnmounted(()=>document.removeEventListener('keydown',keydown))
watch([editing,selected,selectedTask],async()=>{if(modal.value){await nextTick();document.querySelector<HTMLElement>('.milestone-modal button')?.focus()}})
</script>
<template>
 <div class="milestone-live"><div v-if="!projectTasks" class="ml-heading"><div><h2>{{ combined?'里程碑与任务':projectId?'项目里程碑':'阶段与里程碑' }}</h2><p v-if="!combined" class="muted">跟踪关键节点、交付成果和验收进展</p></div><div class="ml-actions"><button v-if="combined&&scoped.some(p=>p.canManageTasks??p.canManage)" @click="emit('edit-task',scoped.find(p=>p.canManageTasks??p.canManage)!)">添加任务</button><button v-if="managed.length" class="pm-inline-action" @click="edit()">新增里程碑</button><template v-if="combined"><button @click="collapsed=[]">展开全部</button><button @click="collapsed=taskGroups.map(g=>g.id)">收起全部</button></template></div></div>
 <div v-if="!combined" class="ml-stats" aria-label="里程碑统计"><div><span>节点总数</span><strong>{{ stats.total }}</strong><small>完成率 {{ stats.total?Math.round(stats.done/stats.total*100):0 }}%</small></div><div><span>已完成</span><strong>{{ stats.done }}</strong></div><div><span>待验收</span><strong>{{ stats.review }}</strong></div><div class="ml-danger"><span>逾期未完成</span><strong>{{ stats.overdue }}</strong></div><div><span>未来7天到期</span><strong>{{ stats.soon }}</strong></div></div>
 <section v-if="!combined" class="panel ml-controls" aria-label="里程碑筛选"><input v-model="query" type="search" aria-label="搜索里程碑" placeholder="搜索节点、项目、负责人、成果或标签"><select v-if="!projectId" v-model="projectFilter" aria-label="里程碑项目筛选"><option value="">全部项目</option><option v-for="p in scoped" :key="p.id" :value="p.id">{{ p.title }}</option></select><select v-if="!projectId" v-model="typeFilter" aria-label="里程碑项目类型"><option value="">全部类型</option><option v-for="type in types" :key="type">{{ type }}</option></select><select v-model="stateFilter" aria-label="里程碑状态筛选"><option value="">全部状态</option><option v-for="state in states" :key="state">{{ state }}</option></select><select v-model="ownerFilter" aria-label="里程碑负责人筛选"><option value="">全部负责人</option><option v-for="[id,name] in owners" :key="id" :value="id">{{ name }}</option></select><select v-model="priorityFilter" aria-label="里程碑优先级筛选"><option value="">全部优先级</option><option v-for="p in ['高','中','低']" :key="p">{{ p }}</option></select><select v-model="dueFilter" aria-label="里程碑日期提醒"><option value="">全部节点</option><option value="逾期">逾期未完成</option><option value="7天内">未来7天到期</option><option value="本人">我负责的节点</option></select><button @click="reset">清空</button></section>
 <div v-if="!combined" class="ml-toolbar"><div role="group" aria-label="里程碑视图"><button v-for="v in ['列表','看板','时间线']" :key="v" :aria-pressed="view===v" :class="{selected:view===v}" @click="view=v">{{ v }}</button></div><div><select v-model="sort" aria-label="里程碑排序"><option value="planned">计划日期从早到晚</option><option value="priority">优先级从高到低</option><option value="progress">进度从高到低</option><option value="updated">最近更新</option></select><button :disabled="!filtered.length" @click="exportExcel">导出</button></div></div>
 <p v-if="error&&!editing" role="alert" class="pm-error">{{ error }}</p>
 <section v-if="combined" class="panel combined-list" :aria-label="projectTasks?'负责项目任务列表':'里程碑与任务列表'"><div class="combined-scroll"><table class="combined-table"><thead><tr><th>{{ projectTasks?'项目/任务名称':'里程碑/任务名称' }}</th><th>任务类型</th><th>负责人</th><th>开始时间/结束时间</th><th>工日</th><th>状态</th><th>进度</th><th>操作</th></tr></thead><tbody v-for="group in taskGroups" :key="group.id" class="combined-group"><tr class="combined-heading"><td><div class="combined-name"><button class="text-link combined-toggle" :aria-label="projectTasks?`展开或收起项目 ${group.project.title}`:`展开或收起里程碑 ${group.milestone?.title||'未关联里程碑的任务'}`" :aria-expanded="!collapsed.includes(group.id)" @click="toggleGroup(group.id)"><span class="fold-icon" aria-hidden="true">{{ collapsed.includes(group.id)?'▸':'▾' }}</span></button><button v-if="projectTasks" class="text-link combined-project-title" @click="emit('open-project',group.project.id)">{{ group.project.title }}</button><button v-else-if="group.milestone" class="text-link combined-title" @click="selected={projectId:group.project.id,id:group.id}">{{ group.milestone.title }}</button><span v-else class="combined-title">未关联里程碑的任务</span><span class="combined-count">（{{ group.tasks.length }}项任务）</span></div></td><td>—</td><td>{{ projectTasks?group.project.owner:group.milestone?.owner||'—' }}</td><td class="combined-dates"><ProjectDateRange v-if="projectTasks" :start="group.project.start" :end="group.project.end" /><span v-else-if="group.milestone" :title="`计划日期：${group.milestone.planned}${group.milestone.actual?'；实际完成：'+group.milestone.actual:''}`"><ProjectDateRange :end="group.milestone.actual||group.milestone.planned" /></span><span v-else>—</span></td><td>—</td><td>{{ projectTasks?group.project.lifecycle:group.milestone?.state||'—' }}</td><td><div v-if="group.milestone" class="combined-progress"><progress :value="group.milestone.progress" max="100" :aria-label="`${group.milestone.title}进度`"></progress><span>{{ group.milestone.progress }}%</span></div><span v-else>—</span></td><td><button v-if="projectTasks" @click="emit('open-project',group.project.id)">进入项目</button><button v-else-if="group.milestone?.canEdit" @click="edit(group.milestone)">编辑里程碑</button></td></tr><template v-if="!collapsed.includes(group.id)"><ProjectTaskTree :tasks="group.tasks" :all-tasks="group.project.tasks" :manage="group.project.canManageTasks??group.project.canManage" @edit="emit('edit-task',group.project,$event)" @view="selectedTask={projectId:group.project.id,id:$event.id}" /><tr v-if="!group.tasks.length"><td colspan="8" class="muted">{{ projectTasks?'本项目暂无任务':'暂无关联任务' }}</td></tr></template></tbody><tbody v-if="projectTasks&&!taskGroups.length"><tr><td colspan="8" class="ml-empty muted">当前没有由您负责的项目</td></tr></tbody></table></div></section>
 <section v-if="!combined&&view==='列表'" class="panel ml-list"><div class="ml-scroll"><table aria-label="里程碑列表"><thead><tr><th>里程碑</th><th v-if="!projectId">所属项目</th><th>负责人</th><th>计划日期</th><th>状态</th><th>进度</th><th>优先级</th><th>交付成果</th><th>操作</th></tr></thead><tbody><tr v-for="m in visible" :key="m.id"><td><button class="text-link ml-name" @click="selected={projectId:m.project.id,id:m.id}">{{ m.title }}</button><small v-if="m.tags.length"><TagPills :tags="m.tags" /></small></td><td v-if="!projectId" class="ml-project-cell"><button class="text-link ml-project-name" @click="emit('open-project',m.project.id)">{{ m.project.title }}</button></td><td>{{ m.owner }}</td><td>{{ m.planned }}</td><td><span class="ml-badge" :class="{done:m.state==='已完成'}">{{ m.state }}</span></td><td><div class="ml-list-progress"><progress :value="m.progress" max="100" :aria-label="`${m.title}进度`"></progress><span>{{ m.progress }}%</span></div></td><td>{{ m.priority }}</td><td class="ml-deliverable">{{ m.deliverable||'—' }}</td><td><div class="ml-actions"><button v-if="m.canEdit" @click="edit(m)">{{ m.canManage?'编辑':'更新进度' }}</button><template v-if="m.canManage"><button @click="edit(m,true)">复制</button><button :disabled="busy" @click="remove(m)">{{ pendingDelete===m.id?'确认删除':'删除' }}</button><button v-if="pendingDelete===m.id" @click="pendingDelete=''">取消</button></template></div></td></tr></tbody></table></div></section>
 <div v-else-if="!combined&&view==='看板'" class="ml-board"><section v-for="state in states" :key="state"><h3>{{ state }} <span>{{ filtered.filter(m=>m.state===state).length }}</span></h3><article v-for="m in filtered.filter(m=>m.state===state)" :key="m.id" class="ml-card"><button class="text-link ml-name" @click="selected={projectId:m.project.id,id:m.id}">{{ m.title }}</button><small v-if="!projectId">{{ m.project.title }}</small><p>{{ m.owner }} · {{ m.priority }}优先级</p><p>{{ m.planned }} · <span :class="{'ml-danger':!closed(m)&&days(m.planned)<0}">{{ timing(m) }}</span></p><progress :value="m.progress" max="100"></progress><small>{{ m.progress }}% · 任务完成 {{ m.completedTasks }}/{{ m.taskCount }}</small><p>{{ m.deliverable||'暂无交付成果说明' }}</p><button v-if="m.canEdit" @click="edit(m)">{{ m.canManage?'编辑':'更新进度' }}</button></article><p v-if="!filtered.some(m=>m.state===state)" class="muted">暂无节点</p></section></div>
 <section v-else-if="!combined" class="panel ml-timeline"><div v-for="p in scoped.filter(p=>filtered.some(m=>m.project.id===p.id))" :key="p.id"><h3>{{ p.title }}</h3><article v-for="m in filtered.filter(m=>m.project.id===p.id).sort((a,b)=>a.planned.localeCompare(b.planned))" :key="m.id"><time>{{ m.planned }}</time><div><button class="text-link ml-name" @click="selected={projectId:p.id,id:m.id}">{{ m.title }}</button><p>{{ m.owner }} · {{ m.state }} · {{ m.progress }}% <span :class="{'ml-danger':!closed(m)&&days(m.planned)<0}">· {{ timing(m) }}</span></p><p>{{ m.deliverable||'暂无交付成果说明' }}</p><small v-if="m.dependsOn">前置节点：{{ p.milestones.find(n=>n.id===m.dependsOn)?.title }}</small></div><button v-if="m.canEdit" @click="edit(m)">更新</button></article></div></section>
 <p v-if="!combined&&!filtered.length" class="panel ml-empty">暂无符合条件的里程碑{{ !rows.length?'，项目负责人可创建关键节点。':'，请调整筛选条件。' }}</p>
 <footer v-if="!combined" class="ml-footer"><span>共 {{ filtered.length }} 个节点 · 统计与导出按当前筛选结果</span><div v-if="view==='列表'"><select v-model.number="pageSize" aria-label="里程碑每页条数"><option :value="10">10条/页</option><option :value="25">25条/页</option><option :value="50">50条/页</option></select><button :disabled="page===1" @click="page--">上一页</button><span>{{ page }} / {{ pages }}</span><button :disabled="page===pages" @click="page++">下一页</button></div></footer>
 </div>
 <div v-if="editing" class="pm-modal milestone-modal"><form class="pm-form ml-form" role="dialog" aria-modal="true" aria-labelledby="milestone-editor-title" @submit.prevent="save"><div class="pm-form-header"><h2 id="milestone-editor-title">{{ editing.entry?(planning?'编辑里程碑':'更新里程碑进度'):'新增里程碑' }}</h2><button type="button" :disabled="busy" @click="editing=undefined">关闭</button></div><div class="pm-form-grid"><label>项目<select v-model="draft.projectId" aria-label="里程碑项目" :disabled="!!editing.entry||!!projectId" @change="selectProject"><option v-for="p in scoped.filter(p=>p.canManage||p.id===editing?.projectId)" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><label>里程碑名称<input v-model.trim="draft.title" required maxlength="150" :disabled="!planning"></label><label>负责人<select v-model="draft.ownerId" aria-label="里程碑负责人" :disabled="!planning"><option v-for="m in current?.members||[]" :key="m.userId" :value="m.userId">{{ m.name }}</option><option v-if="editing.entry&&!current?.members.some(m=>m.userId===draft.ownerId)" :value="draft.ownerId">{{ editing.entry.owner }}（历史成员）</option></select></label><label>计划日期<input v-model="draft.planned" type="date" :min="current?.start" :max="current?.end" required :disabled="!planning"></label><label>优先级<select aria-label="优先级" v-model="draft.priority" :disabled="!planning"><option v-for="p in ['高','中','低']" :key="p">{{ p }}</option></select></label><label>前置里程碑<select aria-label="前置里程碑" v-model="draft.dependsOn" :disabled="!planning"><option value="">无</option><option v-for="m in current?.milestones.filter(m=>m.id!==editing?.entry?.id)||[]" :key="m.id" :value="m.id">{{ m.title }}（{{ m.state }}）</option></select></label></div><label>节点说明<textarea v-model="draft.description" maxlength="5000" :disabled="!planning"></textarea></label><div class="pm-form-grid"><label>交付成果<textarea v-model="draft.deliverable" maxlength="3000" :disabled="!planning" placeholder="应交付的报告、系统或成果"></textarea></label><label>验收标准<textarea v-model="draft.acceptance" maxlength="3000" :disabled="!planning" placeholder="完成节点需要满足的条件"></textarea></label></div><label>标签<input v-model="draft.tags" :disabled="!planning" maxlength="2000" placeholder="用顿号分隔"></label><fieldset :disabled="!planning"><legend>关联任务（可多选）</legend><div class="ml-task-picker"><label v-for="t in current?.tasks||[]" :key="t.id"><input type="checkbox" v-model="draft.taskIds" :value="t.id">{{ t.title }} · {{ t.state }} · {{ t.progress }}%</label><span v-if="!current?.tasks.length" class="muted">本项目暂无任务，可稍后关联</span></div></fieldset><div class="pm-form-grid"><label>节点状态<select aria-label="节点状态" v-model="draft.state" @change="changeState"><option v-for="state in states" :key="state">{{ state }}</option></select></label><label>节点进度（%）<input v-model.number="draft.progress" type="number" min="0" max="100" required :readonly="['待开始','已完成'].includes(draft.state)"></label><label v-if="draft.state==='已完成'">实际完成日期<input v-model="draft.actual" type="date" :max="today()" required></label></div><label>执行记录<textarea v-model="draft.result" maxlength="5000" placeholder="进展、验收结果或暂停原因"></textarea></label><p class="muted">节点进度由负责人维护；关联任务进度独立统计。完成前须完成前置节点及全部关联任务。</p><p v-if="error" role="alert" class="pm-error">{{ error }}</p><div class="pm-form-actions"><button type="button" :disabled="busy" @click="editing=undefined">取消</button><button class="pm-primary" :disabled="busy">{{ busy?'保存中…':'保存里程碑' }}</button></div></form></div>
 <div v-else-if="detail" class="pm-modal milestone-modal"><section class="pm-form ml-form" role="dialog" aria-modal="true" aria-labelledby="milestone-detail-title"><div class="pm-form-header"><h2 id="milestone-detail-title">{{ detail.title }}</h2><button @click="selected=undefined">关闭</button></div><p>{{ detail.project.title }} · {{ detail.owner }} · {{ detail.priority }}优先级</p><p>{{ detail.state }} · {{ detail.progress }}% · {{ timing(detail) }}</p><progress :value="detail.progress" max="100"></progress><dl class="ml-detail"><div><dt>计划日期</dt><dd>{{ detail.planned }}</dd></div><div><dt>实际完成日期</dt><dd>{{ detail.actual||'尚未完成' }}</dd></div><div><dt>节点说明</dt><dd>{{ detail.description||'—' }}</dd></div><div><dt>交付成果</dt><dd>{{ detail.deliverable||'—' }}</dd></div><div><dt>验收标准</dt><dd>{{ detail.acceptance||'—' }}</dd></div><div><dt>前置节点</dt><dd>{{ detail.project.milestones.find(m=>m.id===detail!.dependsOn)?.title||'无' }}</dd></div><div><dt>标签</dt><dd><TagPills :tags="detail.tags" /></dd></div><div><dt>执行记录</dt><dd>{{ detail.result||'—' }}</dd></div></dl><h3>关联任务 · 已完成 {{ detail.completedTasks }}/{{ detail.taskCount }} · 平均进度 {{ detail.taskProgress }}%</h3><ul><li v-for="t in detail.project.tasks.filter(t=>detail!.taskIds.includes(t.id))" :key="t.id">{{ t.title }} · {{ t.owner }} · {{ t.state }} · {{ t.progress }}%</li></ul><p v-if="!detail.taskCount" class="muted">未关联任务</p><small class="muted">最近更新 {{ new Date(detail.updatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }} · 版本 {{ detail.revision }}</small><div class="pm-form-actions"><button v-if="!projectId" @click="emit('open-project',detail.project.id);selected=undefined">进入项目</button><button v-if="detail.canEdit" @click="edit(detail)">{{ detail.canManage?'编辑里程碑':'更新进度' }}</button></div></section></div>
 <div v-if="taskDetail" class="pm-modal milestone-modal"><section class="pm-form ml-form" role="dialog" aria-modal="true" aria-labelledby="task-detail-title"><div class="pm-form-header"><h2 id="task-detail-title">{{ taskDetail.task.title }}</h2><button @click="selectedTask=undefined">关闭</button></div><dl class="ml-detail"><div><dt>所属项目</dt><dd>{{ taskDetail.project.title }}</dd></div><div><dt>任务类型</dt><dd>{{ taskDetail.task.taskType||'未选择' }}</dd></div><div><dt>负责人</dt><dd>{{ taskDetail.task.owner||'—' }}</dd></div><div><dt>参与人员</dt><dd>{{ taskDetail.task.participants?.map(person=>person.name).join('、')||'未选择' }}</dd></div><div><dt>开始时间</dt><dd>{{ taskDetail.task.start||'—' }}</dd></div><div><dt>结束时间</dt><dd>{{ taskDetail.task.due||'—' }}</dd></div><div><dt>状态</dt><dd>{{ taskDetail.task.state }}</dd></div><div><dt>进度</dt><dd>{{ taskDetail.task.progress }}%</dd></div><div><dt>父任务</dt><dd>{{ taskDetail.project.tasks.find(t=>t.id===taskDetail!.task.parentId)?.title||'无' }}</dd></div><div><dt>前置任务</dt><dd>{{ taskDetail.project.tasks.find(t=>t.id===taskDetail!.task.dependsOn)?.title||'无' }}</dd></div><div><dt>关联里程碑</dt><dd>{{ taskDetail.project.milestones.filter(m=>taskDetail!.task.milestoneIds.includes(m.id)).map(m=>m.title).join('、')||'无' }}</dd></div><div><dt>任务描述</dt><dd>{{ taskDetail.task.description||'—' }}</dd></div></dl><div class="pm-form-actions"><button v-if="taskDetail.project.canManage||taskDetail.task.canEdit" @click="editTask(taskDetail.project,taskDetail.task)">{{ (taskDetail.project.canManageTasks??taskDetail.project.canManage)?'编辑任务':'更新进度' }}</button><span v-else class="muted">只有项目管理人员或任务参与人员可修改</span></div></section></div>
</template>
